Action: run_sql({'query': 'SELECT \n    e.gmap_id, \n    e.name, \n    e.address, \n    e.num_of_reviews, \n    e.avg_rating, \n    e.slchd_establishment_key,\n    COUNT(v.violation_id) as violation_count,\n    COUNT(DISTINCT i.inspection_id) as inspection_count\nFROM establishments e\nJOIN inspections i ON e.slchd_establishment_key = i.slchd_establishment_key\nJOIN violations v ON i.inspection_id = v.inspection_id\nGROUP BY e.gmap_id, e.name, e.address, e.num_of_reviews, e.avg_rating, e.slchd_establishment_key\nHAVING COUNT(v.violation_id) > 0\nORDER BY e.num_of_reviews DESC\nLIMIT 10;'})

